fn actor_loop_probed<S: BufRefStore + 'static>(
    mut actor: Box<dyn ActorZC<S> + Send>,
    rx: Receiver<SignalZC<S>>,
    peers: Vec<Sender<SignalZC<S>>>,
    pool: Pool<S>,
    probe_name: String,
) -> (u64, TProbe) {
