    let mut count: u64 = 0;
    loop {
        match rx.recv() {
            Ok(SignalZC::User(msg)) => {
                let mut ctx = MultiCtxZC {
                    senders: &peers,
                    pool: &pool,
                };
                actor.handle_message(&mut ctx, &msg);
                drop(msg);
                count += 1;
            }
            Ok(SignalZC::ClearProbe) => {
                count = 0;
            }
            Ok(SignalZC::QueryCount(reply)) => {
                let _ = reply.send(count);
            }
            Ok(SignalZC::Shutdown) | Err(_) => break,
        }
    }
    count
}"}

