/// Lifecycle surface for a zerocopy actor runtime.
///
/// - `startup` spawns the actor mesh, delivers initial
///   messages, and returns a [`Handle`] the caller drives
///   via [`Handle::run`] / [`Handle::reset_count`] /
///   [`Handle::query_count`] / [`Handle::stop`].
/// - `pool` borrows the runtime's pool handle (initial-
///   message construction, `free_len` / `size` inspection).
/// - Implemented by [`RuntimeZC`]; introduced in `0.6.0-5`
///   so post-`0.6.0` ActorManager-driven graceful-shutdown
///   work has a stable seam to drop into. Consumers
///   (`goalzc`, `goalzc-crit`, lifecycle tests) reach
///   through this trait rather than the concrete type — an
///   `import` here is the compile-time guarantee that the
///   lifecycle surface is the only thing being touched.
/// - Object-safe (`&self` / `&mut self`, no generic params
///   on methods) so a future `dyn Runtime<S>` consumer
///   compiles without additional plumbing.
pub trait Runtime<S: BufRefStore> {
    /// Spawn actor threads and deliver initial messages,
    /// returning a [`Handle`] that owns the actor mesh.
    ///
    /// - The caller drives the lifecycle from there:
    ///   [`Handle::run`] sleeps a run window (any number
    ///   of times); [`Handle::stop`] sends `Shutdown`,
    ///   joins, and returns the aggregate `u64` count.
    /// - No probe support — counts only. Probing re-enters
    ///   post-`0.6.0` via an actor-wrapper trait or
    ///   `TProbe::Counter`.
    /// - On `Drop` without `stop`, the handle does a silent
    ///   shutdown (panics on actor threads are swallowed).
    fn startup(
        &mut self,
        mgr: &mut ActorManager<S>,
        initial_messages: Vec<(u32, PooledMsg<S>)>,
        pin_cores: &[usize],
    ) -> Handle<S>;

    /// Borrow the runtime's pool handle.
    fn pool(&self) -> &Pool<S>;
}

impl<S: BufRefStore + 'static> Runtime<S> for RuntimeZC<S> {
    fn startup(
        &mut self,
        mgr: &mut ActorManager<S>,
        initial_messages: Vec<(u32, PooledMsg<S>)>,
        pin_cores: &[usize],
    ) -> Handle<S> {
        let (senders, handles) =
            self.spawn_and_seed(mgr, initial_messages, pin_cores, actor_loop::<S>);
        Handle {
            senders: Some(senders),
            handles: Some(handles),
            pool: self.pool.clone(),
        }
    }

    fn pool(&self) -> &Pool<S> {
        &self.pool
    }
}"}

