//! struct Echo { peer: u32 }
//! impl<S: BufRefStore> ActorZC<S> for Echo {
//!     fn handle_message(&mut self, ctx: &mut dyn ContextZC<S>, msg: &[u8]) {
//!         let reply = ctx.get_msg(msg.len()).expect("pool sized for steady state");
//!         ctx.send(self.peer, reply);
//!     }
//! }
